import React, { Component } from 'react';
import { inject, observer } from 'mobx-react';
import List from '@material-ui/core/List';
import ListItem from '@material-ui/core/ListItem';
import ListItemText from '@material-ui/core/ListItemText';
import Divider from '@material-ui/core/Divider';
import './SearchResults.css';

@inject('projectStore')
@observer
class SearchResults extends Component {
  render() {
    const {
      projectStore: {
        graphData,
        search: { resultNodeIds }
      }
    } = this.props;
    const resultNodes = resultNodeIds.map(nodeId => graphData.findNode(nodeId));
    return (
      <div>
        <span className="ResultNodeCount">
          {resultNodes.length} Result nodes
        </span>
        <List className="ResultNodeList" subheader={<li />} dense>
          {resultNodes.map(resultNode => (
            <div key={`ResultNode_${resultNode.id}`}>
              <Divider light />
              <ListItem
                dense
                button
                onClick={this.handleResultNodeClick(resultNode.id)}
              >
                <ListItemText>{resultNode.name}</ListItemText>
              </ListItem>
            </div>
          ))}
        </List>
      </div>
    );
  }

  handleResultNodeClick = nodeId => () => {
    const { projectStore } = this.props;
    projectStore.targetLinkChoiceInProgress = false;
    projectStore.activeNode = nodeId;
  };
}

export { SearchResults };
