import { observable, action } from 'mobx';
import notie from 'notie';

import { version as appVersion } from '../package.json';
import Graph from './graph/Graph';
import AvailableTags from './tags/AvailableTags';
import { INITIAL_TAGS_DATA } from './tags/constants';
import Gist from './gist/Gist';
import { GRAPH_STATE_FILENAME } from './gist/constants';
import {
  GRAPH_FORCE_DISTANCE_DEFAULT,
  GRAPH_FORCE_STRENGTH_DEFAULT,
  INITIAL_GRAPH_DATA
} from './constants';
import applyMigrations from './graph/migrator';
import { validateSavedState } from './validator';
import { Search } from './search/Search';

export class ProjectStore {
  githubToken = null;
  @observable gists = null;

  graphData = null;
  @observable availableTags = null;
  @observable search = null;
  @observable isLoaded = false;
  @observable _projectName = '';
  get projectName() {
    return this._projectName;
  }
  set projectName(v) {
    this._projectName = v;
    this.projectGist.setDescription(v);
    document.title = v + ' | Graph editor';
  }

  get isPublic() {
    return this.projectGist._public;
  }

  projectGist = null;
  @action loadProject(gistId) {
    this.projectGist = new Gist(this.githubToken, gistId);
    this.projectGist.read().then(gistInfo => this._initializeGraph(gistInfo));
  }

  @action newProject() {
    this.projectGist = new Gist(this.githubToken);
    const stateForSave = this._prepareStateForSave(
      INITIAL_GRAPH_DATA,
      INITIAL_TAGS_DATA
    );
    const stateJson = JSON.stringify(stateForSave, null, 2);
    this.projectGist
      .create(GRAPH_STATE_FILENAME, stateJson, false, 'New graph')
      .then(gistInfo => this._initializeGraph(gistInfo));
  }

  // TODO: decompose initializeGraph on validate / migrate / initialize
  _initializeGraph(gistInfo) {
    let savedGraphStateJson = gistInfo.files[GRAPH_STATE_FILENAME].content;
    const projectName = gistInfo.description;
    let errorMsg;
    let savedGraphState;
    try {
      savedGraphState = JSON.parse(savedGraphStateJson);
      applyMigrations(savedGraphState);
      // validation type: true / false / errMsg (only true is positive)
      const validation = validateSavedState(savedGraphState);
      if (validation !== true) {
        errorMsg = `Project format "${projectName ||
          'Untitled'}" has invalid data format`;
        if (typeof validation === 'string') {
          errorMsg += ` - ${validation}`;
        }
      }
    } catch (err) {
      errorMsg = `Project "${projectName ||
        'Untitled'}" failed to parse / migrate / validate`;
    }

    if (errorMsg) {
      notie.alert({ type: 'error', text: errorMsg });
      return;
    }

    this.projectName = projectName;
    this.availableTags = new AvailableTags(savedGraphState.tags);
    this.graphData = new Graph(savedGraphState.graph);
    // refill tags data to graph nodes
    this.graphData.getNodeArray().forEach(node => {
      if (node.tags) {
        node.tags = node.tags.map(tagId => this.availableTags.findTag(tagId));
      } else {
        node.tags = [];
      }
    });
    this.forceStrength = savedGraphState.meta.forceStrength;
    this.forceDistance = savedGraphState.meta.forceDistance;
    this.search = new Search(this.graphData);
    this.isLoaded = true;
  }

  _prepareStateForSave(optionalGraphData, optionalTagsData) {
    let graphData = optionalGraphData || this.graphData.getImmutableCopy();
    let availableTagsData =
      optionalTagsData || this.availableTags.getImmutableCopy();
    return {
      graph: graphData,
      tags: availableTagsData,
      meta: {
        forceStrength: this.forceStrength,
        forceDistance: this.forceDistance,
        version: appVersion
      }
    };
  }

  @action saveProject() {
    let result = this._prepareStateForSave();
    const resultJson = JSON.stringify(result, null, 2);
    this.projectGist
      .update(GRAPH_STATE_FILENAME, resultJson)
      .then(responseObj => {
        this.savedChangeStamp = this.changeStamp;
      });
  }

  @observable _activeNode = null;
  get activeNode() {
    return this._activeNode;
  }
  set activeNode(v) {
    if (this._activeNode) {
      this.graphData.findNode(this._activeNode).__focused = false;
    }
    if (v) {
      this.graphData.findNode(v).__focused = true;
    }
    this._activeNode = v;
  }

  @observable targetLinkChoiceInProgress = false;
  @observable changeStamp = 0;
  @observable savedChangeStamp = 0;

  @observable forceStrength = GRAPH_FORCE_STRENGTH_DEFAULT;
  @observable forceDistance = GRAPH_FORCE_DISTANCE_DEFAULT;

  getAfterErrorSnapshot() {
    return {
      graphData: this.graphData ? this.graphData.getImmutableCopy() : null,
      availableTags: this.availableTags
        ? this.availableTags.getImmutableCopy()
        : null,
      forceStrength: this.forceStrength,
      forceDistance: this.forceDistance,
      targetLinkChoiceInProgress: this.targetLinkChoiceInProgress,
      changeStamp: this.changeStamp,
      savedChangeStamp: this.savedChangeStamp,
      gistId: this.projectGist._gistId
    };
  }
}
