/**
 * Style legend:
 * "_data" - is a private data
 * "__data" - is a temporary data
 */

const refillNodes = (savedGraphState) => {
  for (let nodeId in savedGraphState._nodeMap) {
    let node = savedGraphState._nodeMap[nodeId];
    node.tmp = {
      id: Number(nodeId),
      name: node.name,
      links: {},
    };
    Object.defineProperty(node, 'id', {
      get() {
        return this.tmp.id;
      },
    });
  }
};

const refillLinks = (savedGraphState) => {
  for (let linkId in savedGraphState._linkMap) {
    let link = savedGraphState._linkMap[linkId];

    let sourceNode = savedGraphState._nodeMap[link.sourceId];
    sourceNode.tmp.links[linkId] = link;
    let targetNode = savedGraphState._nodeMap[link.targetId];
    targetNode.tmp.links[linkId] = link;

    // for d3 force links
    link.tmp = {
      id: Number(linkId),
      source: sourceNode.tmp,
      target: targetNode.tmp
    };
    Object.defineProperty(link, 'id', {
      get() {
        return this.tmp.id;
      },
    });
  }
};

// TODO: fn in wrong place. graph should not know about tags
const stripTempData = (key, value) => {
  if (key === 'tags') {
    // remove empty tag arrays
    if (value.length === 0) return void 0;

    return value.map(tag => tag.__id); // map tag links to ids
  }

  // remove temp data
  if (key === 'tmp') return void 0;

  return value;
};

export default class Graph {
  _nodeMap = {};
  _linkMap = {};
  _nextNodeId = null;
  _nextLinkId = null;

  constructor(savedGraphState) {
    refillNodes(savedGraphState);
    refillLinks(savedGraphState);

    this._nodeMap = savedGraphState._nodeMap;
    this._linkMap = savedGraphState._linkMap;
    this._nextNodeId = savedGraphState._nextNodeId;
    this._nextLinkId = savedGraphState._nextLinkId;
  }

  getImmutableCopy() {
    const str = JSON.stringify(
      {
        _nodeMap: this._nodeMap,
        _linkMap: this._linkMap,
        _nextNodeId: this._nextNodeId,
        _nextLinkId: this._nextLinkId
      },
      stripTempData,
      2
    );
    return JSON.parse(str);
  }

  addNode(nodeName) {
    let newNode = {
      name: nodeName,
      tags: [],
      tmp: {
        id: this._nextNodeId,
        name: nodeName,
        links: {},
      },
      get id () {
        return this.tmp.id;
      },
    };
    this._nodeMap[this._nextNodeId] = newNode;
    this._nextNodeId++;
    return newNode;
  }

  deleteNode(node) {
    node = this.findNode(node);
    if (Object.keys(node.tmp.links).length > 0) {
      throw new Error('Cannot delete node, when node has links');
    }

    delete this._nodeMap[node.id];
  }

  addLink(sourceId, targetId, type = 'CHILD') {
    if (sourceId === targetId)
      throw new Error('Cannot create link with same sourceId and targetId');

    let oldLinks = this._nodeMap[sourceId].tmp.links;
    for (let oldLinkKey in oldLinks) {
      const oldLink = oldLinks[oldLinkKey];
      if (oldLink.sourceId === sourceId && oldLink.targetId === targetId) {
        throw new Error('Cannot create duplicate links');
      }
    }

    let newLink = {
      type,
      sourceId,
      targetId,
      // for d3 force links
      tmp: {
        id: this._nextLinkId,
        source: this._nodeMap[sourceId].tmp,
        target: this._nodeMap[targetId].tmp,
      },
      get id () {
        return this.tmp.id;
      },
    };
    this._linkMap[this._nextLinkId] = newLink;
    this._nodeMap[sourceId].tmp.links[this._nextLinkId] = newLink;
    this._nodeMap[targetId].tmp.links[this._nextLinkId] = newLink;
    this._nextLinkId++;
    return newLink;
  }

  deleteLink(link) {
    link = this.findLink(link);
    delete this._linkMap[link.id];

    let sourceNode = this._nodeMap[link.sourceId];
    delete sourceNode.tmp.links[link.id];
    let targetNode = this._nodeMap[link.targetId];
    delete targetNode.tmp.links[link.id];
  }

  /**
   * node - nodeId or node
   * result - node
   */
  findNode(node) {
    let result;
    if (typeof node === 'number') {
      result = this._nodeMap[node];
    } else {
      result = node;
    }

    if (!result) throw new Error(`Cannot find node ${node}`);

    return result;
  }

  /**
   * link - linkId or link
   * result - link
   */
  findLink(link) {
    let result;
    if (typeof link === 'number') {
      result = this._linkMap[link];
    } else {
      result = link;
    }

    if (!result) throw new Error(`Cannot find link ${link}`);

    return result;
  }

  getNodeArray(mapper = (node) => node) {
    if (!this._nodeMap) return [];

    return Object.values(this._nodeMap).map(mapper);
  }

  getLinkArray(mapper = (link) => link) {
    if (!this._linkMap) return [];

    return Object.values(this._linkMap).map(mapper);
  }
}
