import React, { Component } from 'react';
import ReactDOM from 'react-dom';
import { inject, observer } from 'mobx-react';
import * as d3 from 'd3';
import { TagLabels } from './TagLabels';
import './GraphView.css';
import debounce from '../utils/debounce';

// Functions and variables
var FORCE;
FORCE = (function(nsp) {
  var width = window.innerWidth,
    height = window.innerHeight,
    // TODO: maybe need d3.forceX and d3.forceY instead of d3.forceCenter
    initForce = (nodes, links, forceOptions) => {
      const { strength, distance } = forceOptions;
      nsp.force = d3
        .forceSimulation(nodes)
        .force('charge', d3.forceManyBody().strength(strength))
        .force(
          'link',
          d3
            .forceLink(links)
            .id(d => d.id)
            .distance(distance)
        )
        .force(
          'center',
          d3
            .forceCenter()
            .x(nsp.width / 2)
            .y(nsp.height / 2)
        )
        .force('collide', d3.forceCollide([5]).iterations([5]));
    },
    enterNode = selection => {
      selection
        .select('circle')
        .attr('r', 25)
        .style('fill', 'tomato')
        .style('stroke', 'bisque')
        .style('stroke-width', '3px');

      selection
        .select('text')
        .style('fill', 'honeydew')
        .style('font-weight', '600')
        .style('text-transform', 'uppercase')
        .style('text-anchor', 'middle')
        .style('alignment-baseline', 'middle')
        .style('font-size', '10px')
        .style('font-family', 'cursive');
    },
    updateNode = selection => {
      selection
        .attr('transform', d => 'translate(' + d.x + ',' + d.y + ')')
        .attr('cx', d => (d.x = Math.max(30, Math.min(width - 30, d.x))))
        .attr('cy', d => (d.y = Math.max(30, Math.min(height - 30, d.y))));
    },
    enterLink = selection => {
      selection.attr('stroke-width', 3).attr('stroke', 'bisque');
    },
    updateLink = selection => {
      selection
        .attr('x1', d => d.source.x)
        .attr('y1', d => d.source.y)
        .attr('x2', d => d.target.x)
        .attr('y2', d => d.target.y);
    },
    updateGraph = selection => {
      selection.selectAll('.node').call(updateNode);
      selection.selectAll('.link').call(updateLink);
    },
    dragStarted = d => {
      if (!d3.event.active) nsp.force.alphaTarget(0.3).restart();

      d.fx = d.x;
      d.fy = d.y;
    },
    dragging = d => {
      d.fx = d3.event.x;
      d.fy = d3.event.y;
    },
    dragEnded = d => {
      if (!d3.event.active) nsp.force.alphaTarget(0);

      d.fx = null;
      d.fy = null;
    },
    initDrag = () =>
      d3.selectAll('g.node').call(
        d3
          .drag()
          .on('start', dragStarted)
          .on('drag', dragging)
          .on('end', dragEnded)
      ),
    initTick = that => {
      that.d3Graph = d3.select(ReactDOM.findDOMNode(that));
      nsp.force.on('tick', () => {
        that.d3Graph.call(updateGraph);
      });
    };

  nsp.width = width;
  nsp.height = height;
  nsp.enterNode = enterNode;
  nsp.updateNode = updateNode;
  nsp.enterLink = enterLink;
  nsp.updateLink = updateLink;
  nsp.updateGraph = updateGraph;
  nsp.initForce = initForce;
  nsp.dragStarted = dragStarted;
  nsp.dragging = dragging;
  nsp.dragEnded = dragEnded;
  nsp.initDrag = initDrag;
  nsp.initTick = initTick;

  return nsp;
})(FORCE || {});

@inject('projectStore')
@observer
class GraphView extends Component {
  componentDidMount() {
    const {
      projectStore: { graphData, forceStrength, forceDistance }
    } = this.props;
    this.reInitForce(graphData, {
      strength: forceStrength,
      distance: forceDistance
    });
  }

  componentDidUpdate(prevProps) {
    const { graphData } = this.props.projectStore;
    if (
      prevProps.changeStamp !== this.props.changeStamp ||
      prevProps.forceStrength !== this.props.forceStrength ||
      prevProps.forceDistance !== this.props.forceDistance
    ) {
      this.reInitForceDebounced(graphData, {
        strength: this.props.forceStrength,
        distance: this.props.forceDistance
      });
    }
  }

  reInitForce = (graphData, forceOptions) => {
    FORCE.initForce(
      graphData.getNodeArray(node => node.tmp),
      graphData.getLinkArray(link => link.tmp),
      forceOptions
    );
    FORCE.initTick(this);
    FORCE.initDrag();
  };

  reInitForceDebounced = debounce(this.reInitForce, 100);

  render() {
    // activeNode observe for highlightning active node
    // eslint-disable-next-line no-unused-vars
    const { graphData, activeNode } = this.props.projectStore;
    let nodes = graphData.getNodeArray().map(node => {
      return <Node key={node.id} data={node} focused={node.__focused} />;
    });
    let links = graphData.getLinkArray().map(link => {
      return <Link key={link.id} data={link} />;
    });
    return (
      <div className="graph_container">
        <svg className="graph" width={FORCE.width} height={FORCE.height}>
          <defs>
            <marker
              id="arrow"
              viewBox="0 0 10 10"
              refX="26"
              refY="5"
              markerWidth="5"
              markerHeight="5"
              orient="auto-start-reverse"
              markerUnits="strokeWidth"
            >
              <path d="M 0 0 L 10 5 L 0 10 z" />
            </marker>
          </defs>
          <g>{links}</g>
          <g>{nodes}</g>
        </svg>
      </div>
    );
  }
}

class Link extends Component {
  componentDidMount() {
    this.d3Link = d3
      .select(ReactDOM.findDOMNode(this))
      .datum(this.props.data.tmp)
      .call(FORCE.enterLink);
  }

  componentDidUpdate() {
    this.d3Link.datum(this.props.data.tmp).call(FORCE.updateLink);
  }

  render() {
    return <line className="link" markerEnd="url('#arrow')" />;
  }
}

@inject('projectStore')
@observer
class Node extends Component {
  componentDidMount() {
    this.d3Node = d3
      .select(ReactDOM.findDOMNode(this))
      .datum(this.props.data.tmp)
      .call(FORCE.enterNode)
      .call(this.processFocus, this.props.focused);
  }

  componentDidUpdate() {
    this.d3Node
      .datum(this.props.data.tmp)
      .call(FORCE.updateNode)
      .call(this.processFocus, this.props.focused);
  }

  processFocus = (d3NodeSelection, isFocused) => {
    d3NodeSelection.select('circle').classed('focused', isFocused);
  };

  render() {
    let {
      // eslint-disable-next-line no-unused-vars
      projectStore: { changeStamp },
      data: { id, tags, name }
    } = this.props;
    return (
      <g className="node" onClick={this.handleClick} data-node-id={id}>
        <circle />
        <text>{name}</text>
        <TagLabels tags={tags} />
      </g>
    );
  }

  handleClick = e => {
    const { projectStore } = this.props;
    if (!projectStore.targetLinkChoiceInProgress) {
      projectStore.activeNode = Number(e.currentTarget.dataset.nodeId);
      return;
    }

    // handle new link creation
    const sourceNodeId = projectStore.activeNode;
    const targetNodeId = Number(e.currentTarget.dataset.nodeId);
    try {
      projectStore.graphData.addLink(sourceNodeId, targetNodeId, 'CHILD');
    } catch (e) {
      console.warn(e.message); // TODO: warn with alertify
      return;
    }
    projectStore.targetLinkChoiceInProgress = false;
    projectStore.changeStamp++;
  };
}

export default GraphView;
