const INCONSISTENT_ID_ERR_MSG_TEMPLATE = ' less or equal than max id from ';

export const validateSavedState = (savedState) => {
  if (
    !isValidDataObject(savedState.graph, {
      _nodeMap: 'object',
      _linkMap: 'object',
      _nextNodeId: 'number',
      _nextLinkId: 'number'
    })
  ) {
    return false;
  }

  if (Math.max(...Object.keys(savedState.graph._nodeMap).map(Number)) >= savedState.graph._nextNodeId) {
    return 'graph._nextNodeId'+ INCONSISTENT_ID_ERR_MSG_TEMPLATE + '_nodeMap';
  }

  if (Math.max(...Object.keys(savedState.graph._linkMap).map(Number)) >= savedState.graph._nextLinkId) {
    return 'graph._nextLinkId'+ INCONSISTENT_ID_ERR_MSG_TEMPLATE + '_linkMap';
  }

  if (
    !isValidDataObject(savedState.tags, {
      _tagMap: 'object',
      _nextTagId: 'number'
    })
  ) {
    return false;
  }

  if (Math.max(...Object.keys(savedState.tags._tagMap).map(Number)) >= savedState.tags._nextTagId) {
    return 'tags._nextTagId'+ INCONSISTENT_ID_ERR_MSG_TEMPLATE + '_tagMap';
  }

  if (
    !isValidDataObject(savedState.meta, {
      forceStrength: 'number',
      forceDistance: 'number',
      version: 'string'
    })
  ) {
    return false;
  }

  return true;
};

const isValidDataObject = (target, requiredProps, optionalProps) => {
  if (target.constructor !== Object) return false;

  const requiredKeys = Object.keys(requiredProps);
  for (let i = 0; i < requiredKeys.length; i++) {
    const property = requiredKeys[i];
    if (!target.hasOwnProperty(property)) return false;

    if (requiredProps[property] === 'object') {
      if (target[property].constructor !== Object) return false;
    } else {
      if (typeof target[property] !== requiredProps[property]) return false;
    }
  }

  if (optionalProps) {
    const optionalKeys = Object.keys(optionalProps);
    for (let i = 0; i < optionalKeys.length; i++) {
      const property = optionalKeys[i];
      if (target.hasOwnProperty(property)) {
        if (typeof target[property] !== optionalProps[property]) return false;
      }
    }
  }

  return true;
};
