import {
  isIntersect,
  ifFullyIntersect,
  isCaseInsensitiveMatch
} from '../utils/common';
import { observable } from 'mobx';

class Search {
  _graph = null;
  @observable searchText = '';
  @observable includedTags = {};
  @observable excludedTags = {};
  @observable resultNodeIds = [];

  constructor(graph) {
    this._graph = graph;
  }

  query() {
    this.resultNodeIds = this._graph
      .getNodeArray()
      .filter(
        node =>
          !isIntersect(
            node.tags.map(tag => tag.__id),
            Object.values(this.excludedTags).map(tag => tag.__id)
          )
      )
      .filter(node =>
        ifFullyIntersect(
          node.tags.map(tag => tag.__id),
          Object.values(this.includedTags).map(tag => tag.__id)
        )
      )
      .filter(node =>
        isCaseInsensitiveMatch([node.name, node.description], this.searchText)
      )
      .map(node => node.id);
  }

  toggleTagInclusion(tag) {
    this._toggleTagMaps(tag, 'includedTags', 'excludedTags');
  }

  toggleTagExclusion(tag) {
    this._toggleTagMaps(tag, 'excludedTags', 'includedTags');
  }

  _toggleTagMaps(tag, targetMapName, oppositeMapName) {
    const tagId = tag.__id;
    if (this[targetMapName][tagId]) {
      delete this[targetMapName][tagId];
      return;
    }

    if (this[oppositeMapName][tagId]) {
      delete this[oppositeMapName][tagId];
    }

    this[targetMapName][tagId] = tag;
  }
}

export { Search };
