import React, { Component } from 'react';
import { inject, observer } from 'mobx-react';
import Accordion from '@material-ui/core/Accordion';
import AccordionSummary from '@material-ui/core/AccordionSummary';
import AccordionDetails from '@material-ui/core/AccordionDetails';
import TextField from '@material-ui/core/TextField';
import Checkbox from '@material-ui/core/Checkbox';
import ClearIcon from '@material-ui/icons/Clear';
import DoneIcon from '@material-ui/icons/Done';
import ExpandMoreIcon from '@material-ui/icons/ExpandMore';
import Button from '../components/Button';
import { Chip } from '../components/Chip';
import { SearchResults } from './SearchResults';
import './SearchPanel.css';

@inject('projectStore')
@observer
class SearchPanel extends Component {
  componentDidUpdate(prevProps) {
    if (prevProps.changeStamp !== this.props.changeStamp) {
      this.query();
    }
  }

  render() {
    const {
      projectStore: { search }
    } = this.props;
    if (!search) return null;

    return (
      <div className="SearchPanel">
        <TextField
          label="Search"
          fullWidth
          variant="outlined"
          margin="dense"
          value={search.searchText}
          onChange={this.handleChangeSearchText}
        />
        {this.renderTagPreferences()}
        <Button onClick={this.query}>Find</Button>
        <SearchResults />
      </div>
    );
  }

  renderTagPreferences = () => {
    const {
      projectStore: { availableTags, search }
    } = this.props;
    const tags = availableTags.getTagArray();
    const tagElems = tags.map(tag => (
      <div key={`search-tag-preference-${tag.__id}`}>
        <Chip name={tag.name} color={tag.color} isActive />
        <Checkbox
          key={`inclusion-tag-${tag.__id}`}
          checked={Boolean(search.includedTags[tag.__id])}
          icon={<DoneIcon fontSize="small" />}
          checkedIcon={<DoneIcon fontSize="small" />}
          onChange={() => search.toggleTagInclusion(tag)}
        />
        <Checkbox
          key={`exclusion-tag-${tag.__id}`}
          checked={Boolean(search.excludedTags[tag.__id])}
          icon={<ClearIcon fontSize="small" />}
          checkedIcon={<ClearIcon fontSize="small" />}
          onChange={() => search.toggleTagExclusion(tag)}
        />
      </div>
    ));

    return (
      <Accordion variant="outlined">
        <AccordionSummary
          expandIcon={<ExpandMoreIcon />}
          id="tags-panel-header"
        >
          Tags
        </AccordionSummary>
        <AccordionDetails>
          {tagElems}
        </AccordionDetails>
      </Accordion>
    );
  };

  handleChangeSearchText = e => {
    this.props.projectStore.search.searchText = e.target.value;
  };

  query = () => {
    const {
      projectStore: { search }
    } = this.props;
    search.query();
  };
}

export { SearchPanel };
