import React, { Component } from 'react';
import { inject, observer } from 'mobx-react';
import './GraphEditPanel.css';
import IconButton from '@material-ui/core/IconButton';
import TextField from '@material-ui/core/TextField';
import DeleteIcon from '@material-ui/icons/Delete';
import CloseIcon from '@material-ui/icons/Close';
import List from '@material-ui/core/List';
import ListItem from '@material-ui/core/ListItem';
import ListItemText from '@material-ui/core/ListItemText';
import ListItemSecondaryAction from '@material-ui/core/ListItemSecondaryAction';
import Button from '../components/Button';
import { Tags } from '../tags/Tags';

@inject('projectStore')
@observer
class GraphEditPanel extends Component {
  state = { activeNode: null, linksHided: false };

  static getDerivedStateFromProps(props, prevState) {
    const { projectStore } = props;
    const { activeNode } = projectStore;
    if (activeNode === prevState.activeNode) return null;

    let node = null;
    let linksHided = false;
    if (activeNode) {
      node = projectStore.graphData.findNode(activeNode);
      // TODO: extract to configuration
      linksHided = Object.keys(node.tmp.links).length > 5;
    }
    return { activeNode, linksHided };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.activeNode !== this.props.activeNode) {
      this.focusNodenameInput();
    }
  }

  render() {
    const { projectStore } = this.props;
    // changeStamp here for observe
    // eslint-disable-next-line no-unused-vars
    const { activeNode, changeStamp } = projectStore;
    let content;
    if (!activeNode) {
      content = (
        <>
          Click on node to edit
          <br />
          or
          <br />
          <Button onClick={this.createNewNode}>create new node</Button>
        </>
      );
    } else {
      const node = projectStore.graphData.findNode(activeNode);
      content = (
        <div>
          <div className="CloseEditPanelButton">
            <IconButton onClick={this.handleCloseEditPanel} size="small">
              <CloseIcon />
            </IconButton>
          </div>
          {this.renderActiveNodeInfo(node)}
          <br />
          <Tags node={node} />
          <br />
          {this.renderLinks(node)}
          {this.renderDeleteNodeButton(node)}
          {this.renderNewLinkComponent(node)}
          {this.renderNewChildButton(node)}
        </div>
      );
    }
    return (
      <div key="graphEditPanel" className="graphEditPanel">
        {content}
      </div>
    );
  }

  focusNodenameInput = () => {
    if (this.nodeNameRef) {
      setTimeout(() => {
        this.nodeNameRef.focus();
      }, 100);
    }
  };

  renderActiveNodeInfo = node => {
    const descriptionContent = node.description ? node.description : '';
    return (
      <>
        <TextField
          label="Node Name"
          fullWidth
          multiline
          variant="outlined"
          margin="dense"
          value={node.name}
          onChange={e => this.handleChangeNodeName(e, node)}
          inputRef={ref => {
            this.nodeNameRef = ref;
          }}
        />
        <br />
        <TextField
          label="Description"
          fullWidth
          multiline
          variant="outlined"
          margin="dense"
          value={descriptionContent}
          onChange={e => this.handleChangeDescription(e, node)}
        />
        <br />
        {'Node ID: '}
        {node.id}
        <br />
      </>
    );
  };

  handleCloseEditPanel = () => {
    const { projectStore } = this.props;
    this.handleAbortNewLinkCreation();
    projectStore.activeNode = null;
  };

  handleChangeNodeName = (e, targetNode) => {
    targetNode.name = e.target.value;
    this.props.projectStore.changeStamp++;
  };

  handleChangeDescription = (e, targetNode) => {
    targetNode.description = e.target.value;
    this.props.projectStore.changeStamp++;
  };

  renderLinks = node => {
    const {
      projectStore: { graphData }
    } = this.props;
    if (this.state.linksHided) {
      return <Button onClick={this.showLinks}>Show links ...</Button>;
    }
    let items = [];
    for (let linkId in node.tmp.links) {
      const link = node.tmp.links[linkId];
      const sourceNode = graphData.findNode(link.sourceId);
      const targetNode = graphData.findNode(link.targetId);
      // TODO: draw arrow instead of source / target text
      items.push(
        <ListItem key={`item-${linkId}`} button>
          <ListItemText>
            <b>source: </b>
            {sourceNode.id}: {sourceNode.name}, <b>target: </b>
            {targetNode.id}: {targetNode.name}
          </ListItemText>
          <ListItemSecondaryAction>
            <IconButton onClick={() => this.handleDeleteLink(link)}>
              <DeleteIcon fontSize="small" />
            </IconButton>
          </ListItemSecondaryAction>
        </ListItem>
      );
    }

    return (
      <>
        <span>Links:</span>
        <List className="links-list" subheader={<li />} dense>
          {items}
        </List>
      </>
    );
  };

  showLinks = () => {
    this.setState({ linksHided: false });
  };

  renderDeleteNodeButton = node => {
    if (Object.keys(node.tmp.links).length > 0) return null;

    return (
      <Button onClick={() => this.handleDeleteNode(node)}>
        Delete this node
      </Button>
    );
  };

  renderNewLinkComponent = () => {
    const { projectStore } = this.props;
    if (!projectStore.targetLinkChoiceInProgress) {
      return (
        <div>
          <Button onClick={this.handleNewLinkTargetSelection}>
            add new link...
          </Button>
          <br />
        </div>
      );
    }

    return (
      <div>
        {'Click on target node to create new link ... '}
        <Button
          onClick={this.handleAbortNewLinkCreation}
          variant="outlined"
          color="secondary"
        >
          cancel
        </Button>
      </div>
    );
  };

  handleAbortNewLinkCreation = () => {
    const { projectStore } = this.props;
    projectStore.targetLinkChoiceInProgress = false;
  };

  renderNewChildButton = node => {
    return (
      <div key="newChild">
        <Button onClick={() => this.handleNewChildCreation(node.id)}>
          add new child...
        </Button>
        <br />
      </div>
    );
  };

  handleDeleteNode = node => {
    const { projectStore } = this.props;
    projectStore.activeNode = null;
    projectStore.graphData.deleteNode(node);
    projectStore.changeStamp++;
  };

  handleDeleteLink = link => {
    const { projectStore } = this.props;
    projectStore.graphData.deleteLink(link);
    projectStore.changeStamp++;
  };

  createNewNode = () => {
    const { projectStore } = this.props;
    const { graphData } = projectStore;
    const newNode = graphData.addNode('new node');
    projectStore.activeNode = newNode.id;
    projectStore.changeStamp++;
  };

  handleNewChildCreation = currentNodeId => {
    const { projectStore } = this.props;
    const { graphData } = projectStore;
    const newNode = graphData.addNode('new child node');
    graphData.addLink(newNode.id, currentNodeId, 'CHILD');
    projectStore.activeNode = newNode.id;
    projectStore.changeStamp++;
  };

  handleNewLinkTargetSelection = () => {
    const { projectStore } = this.props;
    projectStore.targetLinkChoiceInProgress = true;
  };
}

export { GraphEditPanel };
